/* Etapa 1: protótipo visual isolado. Não importa a API nem envia dados. */
const sample = {
  '12': [
    {id:'p12',name:'Produção Setor 1 e 2',type:'MOD',value:12.5},
    {id:'usina12',name:'Usina de Concreto',type:'MOI',value:1},
    {id:'armP',name:'Fab Armação Padrão',type:'MOI',value:3},
    {id:'estribo12',name:'Fab Estribo',type:'MOI',info:'Elias · fator 0,5',value:1},
    {id:'enc12',name:'Encarregado Produção',type:'MOI',info:'Zé Carlos',value:1},
    {id:'sacador12',name:'Sacador núcleo',type:'MOI',info:'Pedro · fator 0,5',value:1},
    {id:'desbob12',name:'Desbobinadeira',type:'MOI',info:'Zezinho · fator 0,5',value:1},
  ],
  '34': [
    {id:'p3',name:'Produção Setor 3',type:'MOD',value:6},
    {id:'p4',name:'Produção Setor 4',type:'MOD',value:3},
    {id:'usina34',name:'Usina de Concreto',type:'MOI',value:1},
    {id:'arm3',name:'Fab Armação setor 3',type:'MOI',value:4},
    {id:'arm4',name:'Fab Armação setor 4',type:'MOI',value:2},
    {id:'estribo34',name:'Fab Estribo',type:'MOI',value:1},
    {id:'enc34',name:'Encarregado Produção',type:'MOI',value:1},
    {id:'sacador34',name:'Sacador núcleo',type:'MOI',value:1},
    {id:'desbob34',name:'Desbobinadeira',type:'MOI',value:1},
  ],
};
const values = Object.fromEntries(Object.entries(sample).map(([group,items]) => [group,Object.fromEntries(items.map(item => [item.id,String(item.value).replace('.',',')]))]));
const requestedScreen = new URLSearchParams(location.search).get('screen');
const state = {screen:['install','launch','review','sent','error','no-production','history'].includes(requestedScreen)?requestedScreen:'launch',group:'12',date:'2026-10-16',reason:'',historyFilter:'all'};
const app = document.getElementById('app');
const fmt = n => Number(n).toLocaleString('pt-BR',{maximumFractionDigits:1});
const groupLabel = group => group === '12' ? 'S1 / S2' : 'S3 / S4';
const dateLabel = date => {const text=new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC',weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(`${date}T12:00:00Z`)).replace(/\.$/,'');return text[0].toUpperCase()+text.slice(1);};
const safe = text => String(text).replace(/[&<>"']/g,char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function totals(){const result={MOD:0,MOI:0};for(const item of sample[state.group]){const value=Number(String(values[state.group][item.id]).replace(',','.'));if(Number.isFinite(value))result[item.type]+=value;}return {...result,total:result.MOD+result.MOI};}
function heading(title='Mão de Obra',eyebrow='Planejamento',back='install',right=true){return `<div class="heading"><div class="heading-left"><button class="icon-button" data-screen="${back}" aria-label="Voltar">‹</button><div class="heading-text"><span class="eyebrow">${eyebrow}</span><strong class="heading-title">${title}</strong></div></div>${right?'<button class="icon-button" data-screen="history" aria-label="Histórico">◴</button>':''}</div>`;}
function reviewRows(){return sample[state.group].map(item=>`<div class="review-item"><span>${safe(item.name)}</span><strong>${safe(values[state.group][item.id]||'0')}</strong></div>`).join('');}
function cards(type){return sample[state.group].filter(item=>item.type===type).map(item=>`<div class="activity-card"><div class="activity-name">${safe(item.name)}${item.info?`<span class="activity-info">${safe(item.info)}</span>`:''}</div><div class="stepper"><button type="button" data-step="-0.5" data-id="${item.id}" aria-label="Diminuir 0,5 em ${safe(item.name)}">−</button><input data-id="${item.id}" inputmode="decimal" autocomplete="off" aria-label="Pessoas em ${safe(item.name)}" value="${safe(values[state.group][item.id])}"><button type="button" data-step="0.5" data-id="${item.id}" aria-label="Aumentar 0,5 em ${safe(item.name)}">+</button></div></div>`).join('');}
function launch(){const t=totals();return `<main class="screen"><header class="hero hero-main">${heading()}<label class="date-label">Data do lançamento<span class="date-box"><span>${dateLabel(state.date)}</span><span aria-hidden="true">▦</span><input id="date" type="date" value="${state.date}" aria-label="Data do lançamento"></span></label><div class="segments" role="group" aria-label="Grupo"><button class="segment ${state.group==='12'?'active':''}" data-group="12">S1 / S2</button><button class="segment ${state.group==='34'?'active':''}" data-group="34">S3 / S4</button></div></header><div class="scroll"><div class="status"><span class="status-dot"></span><strong>Ainda não lançado</strong><span class="muted">· ${groupLabel(state.group)}</span></div><div class="section-heading"><h2>Mão de obra direta</h2><span>MOD <strong data-proto-total="MOD">${fmt(t.MOD)}</strong></span></div><div class="activity-list">${cards('MOD')}</div><div class="section-heading"><h2>Mão de obra indireta</h2><span>MOI <strong data-proto-total="MOI">${fmt(t.MOI)}</strong></span></div><div class="activity-list">${cards('MOI')}</div><div style="height:14px"></div><button class="link-button" data-screen="no-production">Marcar dia sem produção</button></div><footer class="footer"><div class="total-row"><span class="muted" data-proto-total="parts">MOD ${fmt(t.MOD)} + MOI ${fmt(t.MOI)}</span><span>Total <strong data-proto-total="all">${fmt(t.total)}</strong></span></div><button class="primary" data-screen="review">Conferir e enviar <span aria-hidden="true">→</span></button></footer></main>`;}
function install(){return `<main class="screen"><header class="hero install-hero"><div class="app-icon" aria-hidden="true"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0"/><circle cx="17.5" cy="9" r="2.5"/><path d="M16 14.2a5 5 0 0 1 5.5 5.8"/></svg></div><h1>Mão de Obra</h1><p class="brand-sub">Concrefer · Planejamento</p><p>Lance MOD e MOI do dia direto do celular, com ícone próprio na tela inicial.</p></header><div class="install-body"><section class="install-card"><h2>Android (Chrome)</h2><p>Um toque e o app aparece na tela inicial.</p><button class="primary" type="button" data-demo-install>↓ &nbsp; Instalar Mão de Obra</button></section><section class="install-card"><h2>iPhone (Safari)</h2><ol><li>Toque em <strong>Compartilhar</strong> na barra do Safari.</li><li>Escolha <strong>Adicionar à Tela de Início</strong>.</li><li>Confirme o nome <strong>Mão de Obra</strong> e toque em Adicionar.</li></ol></section><div class="install-bottom"><button class="secondary" data-screen="launch">Continuar no navegador</button><span>Usa o mesmo login do Unificado</span></div></div></main>`;}
function review(){const t=totals();return `<main class="screen"><div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="Conferir lançamento"><div class="handle"></div><h1>Conferir lançamento</h1><div class="sheet-sub">${dateLabel(state.date)} · Grupo ${groupLabel(state.group)}</div><div class="summary-grid"><div class="summary-box"><span>MOD</span><strong>${fmt(t.MOD)}</strong></div><div class="summary-box"><span>MOI</span><strong>${fmt(t.MOI)}</strong></div><div class="summary-box total"><span>Total</span><strong>${fmt(t.total)}</strong></div></div><div class="review-list"><div class="review-head"><span>Atividade</span><span>Pessoas</span></div>${reviewRows()}</div><div class="warning"><span aria-hidden="true">ⓘ</span><span>Se este dia já estiver lançado, o envio substitui os valores do grupo ${groupLabel(state.group)} em ${state.date.slice(8,10)}/${state.date.slice(5,7)}.</span></div><div class="sheet-actions"><button class="secondary" data-screen="launch">Voltar e corrigir</button><button class="primary" data-screen="sent">Enviar</button></div><button class="small-link" data-screen="error">Simular falha de conexão</button></section></div></main>`;}
function sent(){const t=totals();return `<main class="screen center-screen"><header class="hero hero-main" style="width:100%">${heading('Mão de Obra','Planejamento','launch',false)}</header><div class="center-content"><div class="check-circle" aria-hidden="true">✓</div><h1>Lançamento enviado</h1><p>Confirmação simulada · nenhum dado foi enviado</p><div class="detail-card"><div class="detail-line"><span>Data</span><strong>${dateLabel(state.date)}</strong></div><div class="detail-line"><span>Grupo</span><strong>${groupLabel(state.group)}</strong></div><div class="detail-line"><span>MOD + MOI</span><strong>${fmt(t.MOD)} + ${fmt(t.MOI)}</strong></div><div class="detail-line detail-total"><span>Total de pessoas</span><strong>${fmt(t.total)}</strong></div><div class="byline">Por gestor de exemplo · PCP</div></div><div class="warning"><span aria-hidden="true">●</span><span>${groupLabel(state.group==='12'?'34':'12')} ainda não foi lançado hoje.</span></div></div><footer class="center-actions"><button class="primary" data-other-group>Lançar ${groupLabel(state.group==='12'?'34':'12')}</button><button class="secondary" data-screen="history">Ver histórico</button></footer></main>`;}
function error(){const t=totals();return `<main class="screen error-screen"><header class="hero hero-main">${heading()}<div class="date-box">${dateLabel(state.date)} · ${groupLabel(state.group)}</div></header><div class="scroll"><div class="error-banner"><span aria-hidden="true">⌁</span><div><strong>Não enviado</strong><span>Verifique a conexão e tente novamente. Seus números foram mantidos neste aparelho.</span></div></div><div class="draft-label">● Rascunho de exemplo · ainda não está no servidor</div><div class="review-list">${reviewRows()}</div><button class="small-link" data-screen="launch">Editar valores</button></div><footer class="footer"><div class="total-row"><span class="muted">MOD ${fmt(t.MOD)} + MOI ${fmt(t.MOI)}</span><span>Total <strong>${fmt(t.total)}</strong></span></div><button class="primary" data-screen="review">Tentar de novo</button></footer></main>`;}
function noProduction(){return `<main class="screen"><div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="Marcar dia sem produção"><div class="handle"></div><div class="no-production-icon" aria-hidden="true">▣</div><h1>Marcar dia sem produção?</h1><p>Todas as atividades deste grupo ficam com 0 e o dia aparece como <strong>sem produção</strong> no histórico e nos relatórios.</p><div class="detail-card"><div class="detail-line"><span>Data</span><strong>${dateLabel(state.date)}</strong></div><div class="detail-line"><span>Grupo</span><strong>${groupLabel(state.group)}</strong></div><div class="detail-line"><span>Atividades zeradas</span><strong>${sample[state.group].length}</strong></div></div><label class="reason">Motivo (opcional)<input id="reason" placeholder="Ex.: feriado, manutenção, chuva" value="${safe(state.reason)}"></label><div class="sheet-actions"><button class="secondary" data-screen="launch">Cancelar</button><button class="navy-button" data-screen="sent">Confirmar</button></div></section></div></main>`;}
const historyRows=[['Sex, 16/10','20,5','Lançado','MOD 12,5 · MOI 8','Pendente','—'],['Qui, 15/10','40','Lançado','MOD 12 · MOI 8','Lançado','MOD 9 · MOI 11'],['Qua, 14/10','42','Lançado','MOD 13 · MOI 8','Lançado','MOD 10 · MOI 11'],['Ter, 13/10','41,5','Lançado','MOD 12,5 · MOI 8','Lançado','MOD 10 · MOI 11'],['Seg, 12/10','0','Sem produção','Feriado','Sem produção','Feriado'],['Sex, 09/10','40','Lançado','MOD 11 · MOI 8','Lançado','MOD 10 · MOI 11']];
function history(){return `<main class="screen"><header class="hero hero-main">${heading('Histórico','Mão de Obra','launch',false)}<div class="segments history-tabs" role="group" aria-label="Filtro de grupo"><button class="segment ${state.historyFilter==='all'?'active':''}" data-filter="all">Todos</button><button class="segment ${state.historyFilter==='12'?'active':''}" data-filter="12">S1 / S2</button><button class="segment ${state.historyFilter==='34'?'active':''}" data-filter="34">S3 / S4</button></div></header><div class="scroll history-scroll"><div class="history-title"><span>OUTUBRO 2026</span><small>1 pendência</small></div>${historyRows.map(row=>`<button class="history-card" data-screen="launch"><div class="history-top"><strong>${row[0]}</strong><span>Total <strong>${row[1]}</strong></span></div>${state.historyFilter!=='34'?`<div class="history-line"><strong>S1/S2</strong><span class="pill ${row[2]==='Sem produção'?'no-production':''}">${row[2]}</span><small>${row[3]}</small></div>`:''}${state.historyFilter!=='12'?`<div class="history-line"><strong>S3/S4</strong><span class="pill ${row[4]==='Pendente'?'pending':row[4]==='Sem produção'?'no-production':''}">${row[4]}</span><small>${row[5]}</small></div>`:''}</button>`).join('')}</div></main>`;}
const screens={install,launch,review,sent,error,'no-production':noProduction,history};
function render(){app.innerHTML=screens[state.screen]();}
function refreshTotals(){const t=totals();for(const [name,value] of Object.entries({MOD:fmt(t.MOD),MOI:fmt(t.MOI),parts:`MOD ${fmt(t.MOD)} + MOI ${fmt(t.MOI)}`,all:fmt(t.total)})){const target=app.querySelector(`[data-proto-total="${name}"]`);if(target)target.textContent=value;}}
app.addEventListener('click',event=>{
  const step=event.target.closest('[data-step]');if(step){const id=step.dataset.id;const n=Number(String(values[state.group][id]).replace(',','.'));values[state.group][id]=fmt(Math.max(0,(Number.isFinite(n)?n:0)+Number(step.dataset.step)));const input=step.closest('.stepper')?.querySelector('input[data-id]');if(input){input.value=values[state.group][id];input.setAttribute('aria-invalid','false');}refreshTotals();return;}
  const group=event.target.closest('[data-group]');if(group){state.group=group.dataset.group;render();return;}
  const filter=event.target.closest('[data-filter]');if(filter){state.historyFilter=filter.dataset.filter;render();return;}
  if(event.target.closest('[data-other-group]')){state.group=state.group==='12'?'34':'12';state.screen='launch';render();return;}
  if(event.target.closest('[data-demo-install]')){alert('Protótipo visual: a instalação será ligada na etapa 5.');return;}
  const target=event.target.closest('[data-screen]');if(target){state.screen=target.dataset.screen;render();}
});
app.addEventListener('change',event=>{if(event.target.id==='date'){state.date=event.target.value||state.date;render();}});
app.addEventListener('input',event=>{const id=event.target.dataset.id;if(id){values[state.group][id]=event.target.value;const value=Number(String(event.target.value).replace(',','.'));event.target.setAttribute('aria-invalid',String(!Number.isFinite(value)||value<0||Math.abs(value*2-Math.round(value*2))>1e-6));refreshTotals();}if(event.target.id==='reason')state.reason=event.target.value;});
render();
